const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'$'+Math.floor(n).toLocaleString(),btn=(a,text,extra='',cls='')=>`<button class="${cls}" data-action="${a}" ${extra}>${text}</button>`;
let s=newState(),slot='guest',saveError=null,hasArchive=false,deviceStatus='Waiting for login',deviceWarning=false,saveSequence=0,authGeneration=0;
const renderer=new Renderer($('world')),ui={selectedArea:null,build:false,tool:null,category:'terrain',brush:2,cursor:null,tab:null,selectedTrainer:null,selectedBuilding:null,follow:null,paused:false,moving:null,battle:null,dexFilter:'',trainerFilter:'',habitat:'meadow'},undo=[],redo=[];
const gameAudio=new GameAudio(),updateChat=createChatUI($('worldChat'),gameAudio);
let lastAuthUid=null;
let lastTime=0,accum=0,renderTick=0,lastSave=0,lastCloud=0,toastTimer,confirmCallback=null,authCreate=false,cloudError='';
let sessionReady=false;
const cloud=new Cloud(c=>{if(c.user&&c.user.uid!==lastAuthUid){lastAuthUid=c.user.uid;loadAccount(c.user.uid);}if(!c.user){authGeneration++;lastAuthUid=null;sessionReady=false;$('authGate').hidden=false;$('game').inert=true;$('welcome').close();}updateHUD();if(ui.tab==='account')renderPanel();});
async function loadAccount(uid){let generation=++authGeneration;sessionReady=false;$('authGate').hidden=false;$('game').inert=true;gateStatus('Loading your saved region…');try{let saved=await deviceLoad(uid),archive=await archiveLoad(uid);if(generation!==authGeneration||cloud.user?.uid!==uid)return;slot=uid;hasArchive=!!archive;s=saved||newState();deviceStatus=saved?'Loaded from this device':'Not saved yet';deviceWarning=false;sessionReady=true;ui.paused=!!saved;ui.build=false;closePanel();$('buildTray').hidden=true;$('authGate').hidden=true;$('game').inert=false;renderer.rev=-1;renderer.areaRev=-1;centerTown();renderer.resize();updateSaveStatus();if(!saved)$('welcome').showModal();else toast('Your region is ready. Press ▶ to resume.');}catch(e){if(generation!==authGeneration)return;gateStatus('Could not read your device save. Nothing was replaced. '+e.message);$('gateRetry').hidden=false;}}
function updateSaveStatus(){let el=$('deviceSaveStatus');if(el){el.hidden=false;el.textContent=deviceStatus;el.classList.toggle('saveFailed',deviceWarning);}let detail=$('deviceSaveDetail');if(detail)detail.textContent=deviceStatus;}

function gateStatus(message=''){ $('authError').textContent=message;$('authTitle').textContent=authCreate?'Create your account':'Welcome back';$('gateSubmit').textContent=authCreate?'Create account':'Log in';$('gateMode').textContent=authCreate?'Already have an account? Log in':'New here? Create an account';$('gatePassword').autocomplete=authCreate?'new-password':'current-password';}

function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4800);}
function ask(title,text){return new Promise(resolve=>{if(confirmCallback)confirmCallback(false);confirmCallback=resolve;$('confirmTitle').textContent=title;$('confirmText').textContent=text;$('confirmDialog').showModal();});}
function answer(value){$('confirmDialog').close();let fn=confirmCallback;confirmCallback=null;fn?.(value);}
$('confirmDialog').addEventListener('cancel',e=>{e.preventDefault();answer(false);});
async function saveLocal(){if(!sessionReady)return false;let id=++saveSequence,saveSlot=slot,saveTime=s.time;deviceStatus='Saving on device…';updateSaveStatus();try{await deviceSave(s,saveSlot);if(id===saveSequence&&saveSlot===slot){lastSave=saveTime;deviceWarning=false;deviceStatus='Device saved · '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'});updateSaveStatus();}return true;}catch(e){if(id===saveSequence&&saveSlot===slot){if(!deviceWarning)toast('Device save failed. Export JSON or save to cloud before leaving.');deviceWarning=true;deviceStatus='NOT SAVED · Export JSON or save to cloud';updateSaveStatus();}return false;}}

function replaceState(next){s=next;undo.length=redo.length=0;ui.follow=null;ui.battle=null;ui.selectedTrainer=null;ui.selectedBuilding=null;renderer.rev=-1;renderer.areaRev=-1;ui.paused=true;saveLocal();updateHUD();}
function centerTown(){let b=s.buildings.find(b=>b.type==='lab');renderer.camera.x=(b?b.x+b.w/2+5:16)*TILE;renderer.camera.y=(b?b.y+b.h+3:17)*TILE;renderer.camera.zoom=innerWidth<700?1.5:1.8;}
function openPanel(tab){s.settings.chatCollapsed=true;if(ui.build){undo.length=redo.length=0;saveLocal();}ui.tab=tab;ui.build=false;ui.moving=null;$('buildTray').hidden=true;$('news').hidden=false;$('panel').hidden=false;renderPanel();updateHUD();}
function closePanel(){ui.tab=null;$('panel').hidden=true;}
function updateHUD(){updateChat(s,ui.build);updateSaveStatus();updateGuide();updateWatchlist();$('regionName').textContent=s.name.toUpperCase();$('money').textContent=money(s.cash);$('population').textContent=s.trainers.length;$('day').textContent='DAY '+(Math.floor(s.time/240)+1);let minutes=Math.floor(s.time%240/240*720)+480;$('clock').textContent=String(Math.floor(minutes/60)).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0');$('speed').textContent=s.settings.speed+'×';$('pause').textContent=ui.paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',ui.paused?'Resume':'Pause');$('watchBtn').classList.toggle('active',!ui.build);$('buildBtn').classList.toggle('active',ui.build);$('modeLabel').textContent=ui.build?'BUILD MODE · WORLD PAUSED':ui.paused?'WORLD PAUSED':'A WORLD OF POSSIBILITIES';$('newsText').textContent=s.journal[0]?.text||'Your story starts here.';$('accountButton').title=cloud.status;$('accountButton').textContent=cloud.user?'☁':'♙';let t=s.trainers.find(t=>t.id===ui.follow);$('followBanner').hidden=!t;if(t)$('followBanner').innerHTML=`Following <b>${esc(t.name)}</b> ${btn('unfollow','×')}`;}
const badges=t=>`<div class="badgeRow">${Array.from({length:8},(_,i)=>`<span class="badge ${t.badges.includes(i+1)?'won':''}">${i+1}</span>`).join('')}</div>`;
const health=f=>`<div class="health ${f.hp/stats(f).hp<.3?'low':''}"><i style="width:${clamp(f.hp/stats(f).hp*100,0,100)}%"></i></div>`;
function feralCard(f,expanded=false){let p=SPECIES[f.species],st=stats(f);return `<div class="card"><div class="row"><img class="portrait" src="${portrait(f)}" alt="${esc(f.species)}"><div class="grow"><div class="title">${f.shiny?'✨ SHINY · ':''}${esc(f.species)} <span class="pill">Lv ${f.level}</span></div><div class="sub">${p.type} · ${Math.ceil(f.hp)} / ${st.hp} HP</div>${health(f)}</div></div>${expanded?`<div class="sub" style="margin-top:9px">${f.moves.map(esc).join(' · ')}</div><div class="sub">ATK ${Math.round(st.attack)} · DEF ${Math.round(st.defense)} · SPD ${Math.round(st.speed)}<br>${f.level>=75?'Maximum level':`${Math.floor(f.xp)} / ${xpToNext(f.level)} XP`} · ${f.wins} wins${p.evo?` · Evolves at Lv ${p.evoLevel}`:''}</div>`:''}</div>`;}
function trainerButton(t){let rank=s.elites.indexOf(t.id);return `<button class="listButton" data-action="trainer" data-id="${t.id}"><div class="row">${t.team[0]?`<img class="portrait" src="${portrait(t.team[0])}" alt="">`:'<span class="rank">♙</span>'}<div class="grow"><div class="title">${t.pinned?'★ ':''}${esc(t.name)}</div><div class="sub">${esc(t.trait)} · ${t.badges.length}/8 badges · ${esc(stateLabel(t))}</div></div><span class="pill">${rank>=0?rank===0?'CHAMPION':'#'+(rank+1):'Lv '+bestLevel(t)}</span></div></button>`;}
function stateLabel(t){if(t.state==='walk'&&t.goal?.areaId){let area=s.areas.find(a=>a.id===t.goal.areaId);if(area)return 'To '+area.name;}if(t.state==='walk')return 'To '+({duelwait:'the duel court',home:'home',homebuy:'a vacant house',jobdesk:'lab quest board',jobclaim:'lab reward desk',jobtask:'job destination',explore:'wild habitat',gym:'gym',heal:'healing lodge',shop:'supply shop',elite:'Elite Four hall',cafe:'trail café'}[t.goal?.state]||'town');return {duelwait:'Waiting for a duel',home:'Resting at home',homebuy:'Buying a house',jobdesk:'Reading the lab quest board',jobtask:'Working on a paid job',jobclaim:'Collecting a quest reward',tournament:'Waiting at the tournament arena',starter:'Choosing a starter',idle:'Planning the next stop',explore:'Searching tall grass',battle:'Battling',gymwait:'Waiting outside the gym',bench:'Resting beside a Feral',heal:'Healing',shop:'Buying supplies',rest:'Resting at camp',elite:'Awaiting challengers',queued:'In the Elite Four queue',climbing:'Climbing the Elite Four',blocked:'Needs a reachable destination',cafe:'Taking a break'}[t.state]||t.state;}
function renderPanel(){if(!ui.tab)return;const body=$('panelBody'),scroll=body.scrollTop;let title='',eyebrow='REGION MANAGEMENT',html='';
 if(ui.tab==='region'){title=s.name;html=`<p class="muted">A place for small beginnings and extraordinary journeys.</p><div class="statGrid"><div><strong>${money(s.cash)}</strong><small>TREASURY</small></div><div><strong>${s.stats.catches}</strong><small>CATCHES</small></div><div><strong>${s.stats.badges}</strong><small>BADGES WON</small></div></div><div class="actions">${btn('panel','🏆 Tournaments','data-tab="tournaments"')}${btn('habitats','Catching areas')}${btn('panel','Journal','data-tab="journal"')}${btn('panel','Help','data-tab="help"')}${btn('panel','Leaderboards','data-tab="leaderboard"')}${btn('panel','Record book','data-tab="records"')}</div><h3>Arrivals</h3><div class="notice">${s.trainers.length} / ${trainerCapacity(s)} trainers · 6 starting places + 6 per gym.<br><span class="tiny">New trainers arrive roughly every 2½–3½ game-minutes. Pause admissions whenever you want.</span></div>${btn('admissions',s.settings.admissions?'Pause new arrivals':'Open trainer admissions','','wide primary')}${economyCard()}<h3>Today’s books</h3><div class="card"><div class="row between"><span>Revenue & grants</span><b>${money(s.daily.revenue)}</b></div><div class="row between"><span>Supplies & upkeep</span><b>${money(s.daily.expenses)}</b></div><div class="row between"><span>End-of-day upkeep</span><b>${money(s.buildings.reduce((n,b)=>n+upkeep(b),0))}</b></div></div><h3>Your buildings</h3>${s.buildings.filter(b=>!DECOR.includes(b.type)).map(b=>`<button class="listButton" data-action="building" data-id="${b.id}"><div class="row between"><span>${esc(b.name)}</span><span class="sub">${b.visits} visits →</span></div></button>`).join('')}<h3>Expand the region</h3><div class="plotGrid">${Array.from({length:6},(_,i)=>`<button data-action="land" data-plot="${i}" class="${s.plots.includes(i)?'owned':''}">${['Homewood','Riverlands','Frostcrest','Marshwild','Crossroads','Ashen Reach'][i]}<br><small>${s.plots.includes(i)?'Owned':money(landCost())}</small></button>`).join('')}</div><h3>Regional grants</h3><p class="tiny muted">Earn grants for your first catch ($125), 10 battles ($200), first badge ($400), three gyms ($600), a trainer with four badges ($800), eight gyms ($1,200), and the first League contender ($600).</p>${s.reports.length?`<h3>Recent days</h3>${s.reports.slice(0,4).map(r=>`<div class="row between tiny"><span>Day ${r.day}</span><span>+${money(r.revenue)} / −${money(r.expenses)}</span></div>`).join('')}`:''}`;}
 else if(ui.tab==='trainers'){title='Your trainers';eyebrow='EVERY TRAINER HAS A STORY';html=`<input id="trainerSearch" placeholder="Find a trainer…" value="${esc(ui.trainerFilter)}" aria-label="Find a trainer"><p class="sub">${s.trainers.length} residents · tap a trainer to see their journey.</p><div id="trainerList">${s.trainers.filter(t=>t.name.toLowerCase().includes(ui.trainerFilter.toLowerCase())).sort((a,b)=>Number(b.pinned)-Number(a.pinned)).map(trainerButton).join('')||'<p class="muted">The first trainers will arrive shortly.</p>'}</div>`;}
 else if(ui.tab==='trainer'){let t=s.trainers.find(t=>t.id===ui.selectedTrainer);if(!t){openPanel('trainers');return;}title=t.name;eyebrow=t.trait.toUpperCase()+' · '+stateLabel(t).toUpperCase();html=`<div class="actions">${btn('follow','Follow on map',`data-id="${t.id}"`,'primary')}${t.battleId?btn('battle','Watch battle',`data-id="${t.battleId}"`):''}${btn('panel','All trainers','data-tab="trainers"')}</div>${trainerExtras(t)}${careerCard(s,t)}${trainerJobCard(t)}${badges(t)}${readinessCard(t)}<div class="statGrid"><div><strong>${money(t.money)}</strong><small>WALLET</small></div><div><strong>${t.orbs}</strong><small>BINDING ORBS</small></div><div><strong>${t.potions}</strong><small>TONICS</small></div></div><div class="row between tiny"><span>${t.wins} wins · ${t.losses} losses</span><span>${t.healthTrips} healing visits</span></div>${t.trophies?.length?'<h3>🏆 Tournament titles · '+t.trophies.length+'</h3>'+t.trophies.slice(-5).map(v=>'<p class="sub">'+esc(v.name)+'</p>').join(''):''}${collectionControls(t)}<h3>Active team · ${t.team.length}/6</h3>${t.team.map(f=>feralCard(f,true)).join('')||'<p>Choosing a starter at the lab…</p>'}${t.storage.length?`<h3>Reserve · ${t.storage.length}</h3>${t.storage.map(f=>feralCard(f)+btn('swap-feral','Move to active team',`data-feral="${f.id}"`,'wide')).join('')}`:''}<h3>Trainer history</h3>${t.history.map(text=>`<div class="event">${esc(text)}</div>`).join('')||'<p class="muted">The journey has only just begun.</p>'}`;}
 else if(ui.tab==='tournaments'||ui.tab==='tourneycreate'){title='Tournaments';eyebrow='BUILD YOUR OWN CIRCUIT';html=tournamentPanel(s,{esc,btn,money},ui.tab==='tourneycreate');}
 else if(ui.tab==='league'){title='The Elite Four';eyebrow='FOUR SEATS. ONE CHAMPION.';let c=s.challenge,t=s.trainers.find(t=>t.id===c?.trainerId);html=`${btn('panel','🏆 Tournaments','data-tab="tournaments"','wide primary')}<p class="muted">Earn eight badges. Defeat #4 to take their seat. Keep winning to climb. #1 is the champion.</p>${s.elites.length?s.elites.map((id,i)=>{let t=s.trainers.find(t=>t.id===id);if(!t)return `<div class="card row"><span class="rank">${i+1}</span><div><b>Unclaimed seat</b><div class="sub">A trainer from your region must earn this place.</div></div></div>`;return `<button class="listButton" data-action="trainer" data-id="${id}"><div class="row"><span class="rank">${i+1}</span><img class="portrait" src="${portrait(t.team[0])}" alt=""><div class="grow"><div class="title">${esc(t.name)}</div><div class="sub">${i===0?'Champion':'Elite Four'} · average Lv ${Math.round(avgLevel(t))}</div></div></div></button>`;}).join(''):`<div class="notice">Build the Elite Four hall. All four seats begin empty; your residents earn them after collecting eight badges.</div>${btn('build-type','Build Elite Four hall · $4,800','data-type="league"','wide primary')}`}<h3>Current challenge</h3>${t?`<div class="card"><b>${esc(t.name)}</b> is challenging rank #${c.target+1}.${t.battleId?btn('battle','Watch live',`data-id="${t.battleId}"`,'wide primary'):'<p class="sub">Traveling to the hall or preparing the next match.</p>'}</div>`:'<p class="muted">The hall is waiting for a challenger.</p>'}<h3>Challenge queue · ${s.queue.length}</h3>${s.queue.map(id=>trainerButton(s.trainers.find(t=>t.id===id))).join('')||'<p class="sub">Only one challenger enters at a time.</p>'}${championHistory()}<h3>Gym circuit</h3>${s.buildings.filter(b=>b.type==='gym').sort((a,b)=>a.order-b.order).map(b=>`<button class="listButton" data-action="building" data-id="${b.id}"><div class="row between"><span>${b.order}. ${esc(b.name)}</span><span class="pill">${b.team.length} FERALS</span></div><div class="sub">${esc(b.leader)} · ${esc(b.badge)} Badge · Lv ${Math.min(...b.team.map(f=>f.level))}–${Math.max(...b.team.map(f=>f.level))}</div></button>`).join('')}<div class="notice tiny">Vacant ranks are claimed in order by the active challenger. Teams are healed between ranked matches. If a challenger loses after gaining a seat, they keep their current rank. A displaced #4 returns to training and can retry later.</div>`;}
 else if(ui.tab==='building'){let b=s.buildings.find(b=>b.id===ui.selectedBuilding);if(!b){closePanel();return;}title=b.name;eyebrow=b.type==='gym'?'GYM '+b.order+' · '+b.badge.toUpperCase()+' BADGE':BUILDINGS[b.type].name.toUpperCase();ensureLiving(s);html=`<div class="statGrid"><div><strong>${b.visits}</strong><small>VISITS</small></div><div><strong>${money(b.revenue)}</strong><small>REVENUE</small></div><div><strong>${money(upkeep(b))}</strong><small>DAILY UPKEEP</small></div></div>${b.type==='gym'?`<p>Leader <b>${esc(b.leader)}</b> · ${b.team.length} Ferals</p>${b.team.map(f=>`<div class="card row"><img class="portrait" src="${portrait(f)}" alt=""><div><b>${esc(f.species)}</b><div class="sub">Lv ${f.level} · ${(f.moves.length?f.moves:defaultMoves(f.species,f.level)).map(esc).join(' · ')}</div></div></div>`).join('')}${btn('edit-gym','Edit leader, badge & team','','wide primary')}`:''}${buildingExtras(b)}<label>Building name<input id="buildingName" maxlength="45" value="${esc(b.name)}"></label>${['heal','shop','gym','league','cafe','duel'].includes(b.type)?`<label>${b.type==='duel'?'Spectator ticket price':b.type==='shop'?'Price per binding orb':'Service / entry fee'} ($)<input id="buildingFee" type="number" min="0" max="150" value="${b.fee}"></label><p class="sub">${b.type==='duel'?'Spectators pay once when arriving; trainer entry is free. Set tickets between $0 and $15.':b.type==='shop'?'Orbs cost you $6 each; tonics sell for $24 and cost $10.':'Trainers pay what they can afford. Healing remains available to broke trainers.'}</p>`:''}<div class="actions">${btn('save-building','Save settings','','primary')}${btn('move-building','Move · $80')}</div>${!['lab','gym','league'].includes(b.type)?btn('remove-building','Remove · 50% refund','','wide danger'):''}<p class="sub">Entrance must remain reachable from the starter lab.</p>`;}
 else if(ui.tab==='gymedit'){let b=s.buildings.find(b=>b.id===ui.selectedBuilding);title='Design your gym';eyebrow='GYM '+b.order+' · FULL TEAM CONTROL';html=`<label>Leader name<input id="leaderName" maxlength="35" value="${esc(b.leader)}"></label><label>Badge name<input id="badgeName" maxlength="30" value="${esc(b.badge)}"></label><p class="sub">Choose 1–6 Ferals. Each can use up to four moves of your choice. Leaving moves blank gives the species its level-appropriate moves.</p>${Array.from({length:6},(_,i)=>{let f=b.team[i];return `<details ${i===0?'open':''}><summary id="gymSummary${i}">Slot ${i+1}${f?' · '+esc(f.species):' · empty'}</summary>${gymPickerHTML(f,i)}<label>Level<input id="gymLevel${i}" type="number" min="1" max="75" value="${f?.level||7}"></label>${Array.from({length:4},(_,j)=>`<label>Move ${j+1}<select id="gymMove${i}-${j}"><option value="">Automatic / none</option>${Object.keys(MOVES).map(k=>`<option ${f?.moves?.[j]===k?'selected':''}>${esc(k)}</option>`).join('')}</select></label>`).join('')}</details>`;}).join('')}${btn('save-gym','Save gym team','','wide primary')}${btn('building','Back',`data-id="${b.id}"`,'wide')}<p class="sub">Changes apply to future battles. An ongoing match keeps the team it started with.</p>`;}
 else if(ui.tab==='areas'){title='Your catching areas';eyebrow='DRAW THE ROUTE. CHOOSE THE FERALS.';html=`<p class="muted">Each area is a place you create on the map. Name it, paint its boundary, select its Ferals, and open it to trainers.</p>${btn('new-area','Create a catching area','','wide primary')}${(s.areas||[]).map((a,i)=>`<button class="listButton" data-action="area" data-id="${a.id}"><div class="row between"><b>${i+1}. ${esc(a.name)}</b><span class="pill">${a.open?'OPEN':'CLOSED'}</span></div><div class="sub">Lv ${a.min}–${a.max} · ${a.cells.length} tiles · ${a.requiredBadges} badges required</div><div class="sub">${a.species.length?a.species.map(esc).join(', '):'Auto roster · '+TERRAIN[a.biome].name}</div></button>`).join('')||'<div class="notice">No areas yet. Natural terrain does not create encounters until you mark and open an area.</div>'}`;}
 else if(ui.tab==='area'){let a=s.areas.find(a=>a.id===ui.selectedArea);if(!a){openPanel('areas');return;}title=a.name;eyebrow='CATCHING AREA · '+(a.open?'OPEN':'CLOSED');html=`<p class="sub">${a.cells.length} marked tiles. Trainers travel to this area by name. Select a badge requirement to keep beginners out of later routes.</p><label>Area name<input id="areaName" maxlength="45" value="${esc(a.name)}"></label><label>Scenery / auto-population biome<select id="areaBiome">${HABITATS.map(k=>`<option value="${k}" ${a.biome===k?'selected':''}>${TERRAIN[k].name}</option>`).join('')}</select></label><div class="formRow"><label>Minimum level<input id="areaMin" type="number" min="1" max="75" value="${a.min}"></label><label>Maximum level<input id="areaMax" type="number" min="1" max="75" value="${a.max}"></label></div><label>Badges needed to enter<input id="areaBadges" type="number" min="0" max="8" value="${a.requiredBadges}"></label><label><input id="areaAuto" type="checkbox" ${a.species.length?'':'checked'}> Auto-populate from this biome</label>${areaPickerHTML()}<p class="sub">Weights are relative: 100 common, 20 rare, 4 epic. Zero disables a species. These change appearance odds, not capture odds. Save to recalculate percentages.</p>${areaOdds(a)}${btn('save-area','Save area settings','','wide primary')}<div class="actions">${btn('paint-area','Paint / expand',`data-id="${a.id}"`)}${btn('erase-area','Erase tiles',`data-id="${a.id}"`)}</div>${btn('toggle-area',a.open?'Close area':'Open to trainers',`data-id="${a.id}"`,'wide gold')}<div class="actions">${btn('find-area','Find marker',`data-id="${a.id}"`)}${btn('remove-area','Remove area',`data-id="${a.id}"`,'danger')}</div><p class="sub">Paint costs $3 per new tile. Terrain stays after removing a boundary. With mixed rosters, rarer species appear less often. Rare species also have lower catch odds.</p>`;}
 else if(ui.tab==='dex'){title='The Feral-dex';eyebrow=Object.keys(SPECIES).length+' ORIGINAL FERALS';html=`<input id="dexSearch" placeholder="Search species or element…" value="${esc(ui.dexFilter)}" aria-label="Search Ferals"><p class="sub">Meet the creatures that make your region their home.</p><div id="dexGrid" class="dexGrid">${dexList()}</div>`;}
 else if(ui.tab==='species'){let p=SPECIES[ui.species];title=p.name;eyebrow=p.type.toUpperCase()+' · '+TERRAIN[p.habitat].name.toUpperCase();html=`<div style="text-align:center"><img src="${portrait(p.name)}" width="160" height="160" style="image-rendering:pixelated" alt="${esc(p.name)}"></div><p>${esc(p.lore)}</p>${speciesStatsCard(s,p.name)}<div class="statGrid"><div><strong>${p.hp}</strong><small>BASE HEALTH</small></div><div><strong>${p.attack}</strong><small>BASE ATTACK</small></div><div><strong>${p.defense}</strong><small>BASE DEFENSE</small></div></div><p class="sub">${p.rarity>=5?'Rare':p.rarity>=3?'Uncommon':'Common'} · ${p.evo?'Evolves into '+p.evo+' at level '+p.evoLevel:'Final form'}</p><h3>Element matchups</h3><p class="tiny">Strong against: ${TYPES[p.type].strong.join(', ')}<br>Less effective against: ${TYPES[p.type].weak.join(', ')}</p><h3>Natural moves</h3>${defaultMoves(p.name,75).map(k=>`<div class="row between tiny"><span>${k}</span><span>${MOVES[k].power} power</span></div>`).join('')}${btn('panel','Back to Feral-dex','data-tab="dex"','wide')}`;}
 else if(ui.tab==='leaderboard'){title='Trainer leaderboards';eyebrow='THE REGION’S STANDOUTS';html=leaderboardPanel(s,ui.leaderboardMetric||'wins');}
 else if(ui.tab==='records'){title='Region record book';eyebrow='FIRSTS, MILESTONES & LEGENDS';html=recordsPanel(s);}
 else if(ui.tab==='journal'){title='Region activity';eyebrow='TAP AN EVENT TO FOLLOW ITS STORY';html=activityFeed();}
 else if(ui.tab==='battle'){let b=s.battles.find(b=>b.id===ui.battle);title=b?b.type==='elite'?'A seat at the top':b.type==='gym'?'Badge challenge':b.type==='wild'?'Wild encounter':'Trainer battle':'Battle complete';eyebrow='LIVE · AUTOMATIC TURN-BASED BATTLE';if(b){let a=active(b,'a'),bb=active(b,'b');html=`<div class="row between tiny"><b>${esc(b.a.name)}</b><b>${esc(b.b.name)}</b></div><div class="battleNames"><div id="battleSideA">${a?`${esc(a.species)} · Lv ${a.level}${health(a)}`:''}</div><div id="battleSideB">${bb?`${esc(bb.species)} · Lv ${bb.level}${health(bb)}`:''}</div></div><canvas id="battleCanvas" class="battleCanvas" width="600" height="350"></canvas><div id="battleSummary" class="notice" style="margin:10px 0">${b.done?b.winner==='capture'?`${esc(b.a.name)} caught ${esc(b.captured.species)}!`:`${esc(b[b.winner].name)} wins!`:`Round ${b.round} · ${esc(b.last?.text||'Sending out Ferals…')}`}</div><div id="battleLog" class="battleLog">${b.log.map(esc).join('<br>')}</div><div class="actions">${btn('trainer','Trainer profile',`data-id="${b.a.id}"`)}${btn('battle-map','View on map',`data-id="${b.id}"`)}</div><p class="sub">Turns play automatically. Use the speed control to change the pace.</p>`;}else html='<p>The trainers have moved on. Their results are recorded in their profiles.</p>'+btn('panel','Find a trainer','data-tab="trainers"','wide');}
 else if(ui.tab==='installhelp'){title='Install Feral Regions';eyebrow='ADD THE GAME TO YOUR HOME SCREEN';html=`<p class="notice">${esc(installDescription())}</p>${btn('install','Try installation prompt','','wide primary')}<h3>Samsung / Android</h3><ol><li>Open the game address below directly in Chrome or Samsung Internet.</li><li>Open the browser’s ⋮ or ☰ menu.</li><li>Choose Install app or Add to Home screen, then confirm.</li></ol><h3>iPad</h3><p>Open the address in Safari → Share → Add to Home Screen → Add.</p><label>Game address<input readonly value="${esc(gameInstallURL())}" aria-label="Published game address"></label>${btn('copy-install-link','Copy game address','','wide')}<p class="sub">If the browser itself says “already installed” but cannot open the app, send a screenshot of that message. This game cannot verify or repair the browser’s app registration. Don’t clear game data to try to fix installation.</p>${installationError()?'<p class="error">'+esc(installationError())+'</p>':''}${btn('panel','Back to Account','data-tab="account"','wide')}`;}
 else if(ui.tab==='account'){title='Account & saves';eyebrow='YOUR REGION, WHEREVER YOU GO';html=`<div class="notice"><b>${esc(cloud.status)}</b><br><span class="tiny">Device autosave runs every 10 seconds. No time passes while the game is closed.</span></div><p id="deviceSaveDetail" class="${deviceWarning?'error':'sub'}">${esc(deviceStatus)}</p>${btn('device-save','Save on this device now','','wide')}${cloudError?`<p class="error">${esc(cloudError)}</p>`:''}${cloud.user?`<p>Signed in as <b>${esc(cloud.user.email||cloud.user.displayName||'Trainer')}</b></p><p class="sub">Load your cloud region or explicitly save this device’s region. After choosing, cloud autosaves run once per minute while playing.</p><div class="actions">${btn('cloud-load','Load cloud region','','primary')}${btn('cloud-save','Save this region')}</div>${btn('signout','Sign out','','wide')}`:`<p>Sign in to save your private region across devices.</p>${btn('google','Continue with Google','','wide primary')}<hr><label>Email<input id="email" type="email" autocomplete="email" placeholder="you@example.com"></label><label>Password<input id="password" type="password" autocomplete="${authCreate?'new-password':'current-password'}" minlength="6" placeholder="At least 6 characters"></label><div class="actions">${btn('email-auth',authCreate?'Create account':'Sign in','','primary')}${btn('auth-mode',authCreate?'Have an account?':'Create an account')}</div>${btn('reset-password','Reset password','','wide')}`}${hasLegacyGuest()?btn('recover-guest','Recover my older guest region','','wide'):''}<h3>Portable backup</h3><div class="actions">${btn('export','Export JSON')}${btn('import','Import JSON')}</div><h3>Region settings</h3><label>Region name<input id="renameRegion" maxlength="48" value="${esc(s.name)}"></label>${btn('rename','Rename region','','wide')}${btn('sound',s.settings.sound?'Sound: on':'Sound: off','','wide')}<h3>Install Feral Regions</h3><p class="sub">${esc(installDescription())}</p>${btn('install','Install on your device','','wide primary')}<p class="sub">Android: browser menu → Install app / Add to home screen.<br>iPad: Safari → Share → Add to Home Screen → Add.<br>Install from your published HTTPS GitHub Pages address. Account login and cloud saves need an internet connection.</p>${installationError()?'<p class="error">'+esc(installationError())+'</p>':''}${hasAppUpdate()?btn('app-reload','Save & load the app update','','wide'):''}<h3>Fresh start</h3>${btn('new-region','Start a new empty region','','wide')}${hasArchive?btn('restore-region','Restore previous region','','wide'):''}<p class="sub">Starting fresh archives this device’s current region and pauses cloud uploads until you choose to save the new one.</p><p class="sub">Feral Regions v${VERSION} · GitHub Pages edition</p>`;}
 else if(ui.tab==='help'){title='A world worth watching';eyebrow='QUICK FIELD GUIDE';html=`<h3>Touch controls</h3><p>In Watch, drag to pan and pinch to zoom. Tap a trainer, building, or battle to inspect it. Follow a trainer to stay with their journey.</p><p>In Build, one finger paints or places. Two fingers move and zoom. The hand tool pans with one finger. Building pauses the world; Undo and Redo work until you return to Watch.</p><h3>Your first expansion</h3><p>Start with empty land. Place a starter lab, healing lodge, and shop, then paint your own paths. Open admissions when you are ready. Draw your first catching area, add a gym when ready, then expand into new land. Population capacity is six plus six per gym, up to 54 total. Place bridges over rivers. Regional grants help fund new gyms.</p><h3>Trainer decisions</h3><p>Create catching areas from Build → Areas. Name and paint each area, choose its roster and levels, and open it. Trainers visit eligible marked areas near their level. Unmarked terrain produces no encounters. They weaken unfamiliar Ferals and get one low-chance orb attempt per encounter, carry six active teammates and six reserves, heal when hurt, and buy supplies. Field research provides income, so a broke trainer can recover.</p><p>Gym challenges require a healthy team and a leading Feral close to the gym’s highest level. After a loss, trainers train before retrying. Use each area’s level range and badge requirement to control access to later routes. Teams are rebalanced after catches and healing for strength and elemental coverage. If all twelve slots are full, a successful new catch replaces a weak reserve.</p><h3>Build the league</h3><p>Build eight gyms with the teams you want. Then build the Elite Four hall. The hall starts empty. Your own eight-badge trainers establish its first four residents. Only one contender challenges at a time.</p><p>A win over #4 takes that seat. Each subsequent win swaps the challenger with the next rank up. A loss ends the run but preserves any seat earned. Defeated #4 trainers return to the world. #1 is the champion.</p><h3>Economy</h3><p>Shops, healing, gym entry, league entry, and cafés earn money. Supplies and daily upkeep cost money. Trainers receive field-research rewards and a small daily guild stipend. Keep prices affordable.</p><h3>Blocked trainers</h3><p>A “!” means the trainer cannot reach a suitable destination. Connect your buildings and habitats with dry land or bridges. Add a healing lodge near distant routes.</p><h3>Time & saving</h3><p>A region day lasts four minutes at 1×. Pause, 1×, 2× and 4× are available. Closing or hiding the game pauses it; there is no offline catch-up. Export backups from Account.</p>`;}
 $('panelTitle').textContent=title;$('panelEyebrow').textContent=eyebrow;body.innerHTML=html;if(ui.tab==='area')mountAreaPicker(s.areas.find(a=>a.id===ui.selectedArea));body.scrollTop=scroll;if(ui.tab==='tourneycreate')updatePrizePreview($);
}
function dexList(){return Object.values(SPECIES).filter(p=>(p.name+' '+p.type).toLowerCase().includes(ui.dexFilter.toLowerCase())).map(p=>`<button data-action="species" data-species="${esc(p.name)}"><img src="${portrait(p.name)}" alt=""><b>${esc(p.name)}</b><small>${p.type.toUpperCase()}</small></button>`).join('');}
function landCost(){return 2200+(s.plots.length-1)*1000;}
function editSnapshot(){return {ledger:structuredClone(s.ledger||[]),cash:s.cash,tiles:[...s.tiles],buildings:structuredClone(s.buildings),areas:structuredClone(s.areas),navVersion:s.navVersion,expenses:s.stats.expenses,dailyExpenses:s.daily.expenses};}
function restoreEdit(v){s.ledger=structuredClone(v.ledger||[]);s.cash=v.cash;s.tiles=[...v.tiles];s.buildings=structuredClone(v.buildings);s.areas=structuredClone(v.areas||[]);s.stats.expenses=v.expenses;s.daily.expenses=v.dailyExpenses;invalidate(s);renderer.rev=-1;}
function commitEdit(before){undo.push(before);if(undo.length>20)undo.shift();redo.length=0;invalidate(s);saveLocal();updateHUD();renderBuild();}
function enterBuild(type=null){s.settings.chatCollapsed=true;closePanel();ui.build=true;ui.tool=type;ui.cursor=null;ui.placement=null;ui.moving=null;ui.follow=null;$('news').hidden=true;$('buildTray').hidden=false;if(type){ui.tool=type;ui.category=['area','areaErase'].includes(type)?'areas':TERRAIN[type]?'terrain':BUILDINGS[type]&&DECOR.includes(type)?'decor':'buildings';}renderBuild();updateHUD();}
function renderBuild(){let oldList=$('buildTray').querySelector('.toolList'),paletteScroll=ui.paletteCategory===ui.category?(oldList?.scrollLeft||0):0;ui.paletteCategory=ui.category;let selectedArea=s.areas.find(a=>a.id===ui.selectedArea);let keys=ui.category==='areas'?[]:ui.category==='terrain'?Object.keys(TERRAIN):ui.category==='decor'?DECOR:['lab','heal','shop','gym','league','cafe','house','duel','arena','stands'];$('buildTray').innerHTML=`<div class="buildHeader"><div class="buildTabs">${['terrain','buildings','decor','areas'].map(k=>btn('build-category',k[0].toUpperCase()+k.slice(1),`data-category="${k}"`,ui.category===k?'active':'')).join('')}</div><span>${BUILDINGS[ui.tool]?'Drag on the map, release to place':!ui.tool?'Choose a tool · drag the map to pan':'Paint your next adventure'}</span>${btn('tool','✋','data-tool="pan"',ui.tool==='pan'?'active':'')}</div><div class="toolShelf"><button class="paletteArrow" data-action="palette-scroll" data-direction="-1" aria-label="Previous build tools">‹</button><div class="toolList" aria-label="Build tools. Swipe sideways to browse.">${ui.category==='areas'?btn('new-area','+ New area')+(s.areas||[]).map(a=>btn('paint-area',esc(a.name),`data-id="${a.id}"`,ui.selectedArea===a.id?'active':'')).join(''):''}${keys.map(k=>{let d=TERRAIN[k]||BUILDINGS[k];return `<button data-action="tool" data-tool="${k}" class="${ui.tool===k?'active':''}"><i class="toolSwatch" style="background:${d.color}"></i>${d.name}<small>${money(d.cost)}${TERRAIN[k]?' / tile':''}</small></button>`;}).join('')}</div><button class="paletteArrow" data-action="palette-scroll" data-direction="1" aria-label="More build tools">›</button></div><div class="buildFooter">${TERRAIN[ui.tool]||['area','areaErase'].includes(ui.tool)?`<span>Brush</span><input id="brush" aria-label="Brush size" type="range" min="1" max="5" value="${ui.brush}"><span>${ui.brush} tiles</span>`:''}${btn('undo','↶ Undo','',undo.length?'':'disabled')}${btn('redo','↷ Redo','',redo.length?'':'disabled')}${ui.category==='areas'&&selectedArea?btn('area','Edit / open '+esc(selectedArea.name),`data-id="${selectedArea.id}"`):''}<span class="hint">Two fingers to pan / zoom</span>${btn('watch','Done','','primary')}</div>`;$('buildTray').querySelector('.toolList').scrollLeft=paletteScroll;}
function validateRoutes(){s._navigationVersion=-1;s._navCache=null;let lab=s.buildings.find(b=>b.type==='lab');if(!lab)return !s.trainers.length;let origin=door(lab);return s.buildings.filter(b=>!DECOR.includes(b.type)).every(b=>navPath(s,origin,door(b)))&&s.trainers.every(t=>walkable(s,Math.round(t.x),Math.round(t.y)));}
async function place(x,y){let type=ui.tool;if(!BUILDINGS[type])return;if(s.buildings.length>=300){toast('This region has reached its 300-building limit.');return;}if(['lab','league'].includes(type)&&s.buildings.some(b=>b.type===type)&&!ui.moving){toast('Your region already has one. Select it to move it.');return;}let n=s.buildings.filter(b=>b.type==='gym').length;if(type==='gym'&&n>=8&&!ui.moving){toast('All eight gyms are built. Select one to customize it.');return;}let error=canPlace(s,type,x,y,ui.moving);if(error){toast(error);return;}let price=ui.moving?80:BUILDINGS[type].cost;if(s.cash<price){toast('Not enough money. Let your region earn more first.');return;}if(!await ask(ui.moving?'Move building?':`Build ${BUILDINGS[type].name}?`,`${money(price)} from your treasury. Entrance faces down toward the path.`))return;let before=editSnapshot();let moving=ui.moving;if(moving){let b=s.buildings.find(b=>b.id===moving);b.x=x;b.y=y;ui.moving=null;}else s.buildings.push(makeBuilding(type,x,y,n));ensureLiving(s);if(!validateRoutes()){restoreEdit(before);toast('That location blocks an existing entrance or trainer.');return;}expense(s,price);gameAudio.play('build');ui.tool=null;ui.cursor=null;ui.placement=null;commitEdit(before);if(type==='league'&&!moving){seedElites(s);undo.length=redo.length=0;saveLocal();}toast(moving?'Building moved.':`${BUILDINGS[type].name} is open.`);}
function paintAt(x,y){if(['area','areaErase'].includes(ui.tool)){paintArea(x,y);return;}let r=Math.floor(ui.brush/2);for(let yy=y-r;yy<y-r+ui.brush;yy++)for(let xx=x-r;xx<x-r+ui.brush;xx++){if(!owned(s,xx,yy)||buildingAt(s,xx,yy)||s.buildings.some(b=>door(b).x===xx&&door(b).y===yy)||s.trainers.some(t=>Math.round(t.x)===xx&&Math.round(t.y)===yy))continue;let i=idx(xx,yy);if(s.tiles[i]===ui.tool)continue;let cost=TERRAIN[ui.tool]?.cost;if(!cost||s.cash<cost)continue;s.tiles[i]=ui.tool;expense(s,cost);strokeChanged=true;}renderer.rev=-1;}
function paintArea(x,y){let area=s.areas.find(a=>a.id===ui.selectedArea);if(!area)return;let radius=Math.floor(ui.brush/2);for(let yy=y-radius;yy<y-radius+ui.brush;yy++)for(let xx=x-radius;xx<x-radius+ui.brush;xx++){if(!owned(s,xx,yy))continue;let i=idx(xx,yy);if(ui.tool==='areaErase'){if(area.cells.includes(i)){area.cells=area.cells.filter(n=>n!==i);strokeChanged=true;}continue;}if(buildingAt(s,xx,yy)||s.buildings.some(b=>door(b).x===xx&&door(b).y===yy)||terrain(s,xx,yy)==='water'||terrain(s,xx,yy)==='bridge'||s.areas.some(a=>a.id!==area.id&&a.cells.includes(i)))continue;if(!area.cells.includes(i)&&s.cash>=3){area.cells.push(i);s.tiles[i]=area.biome;expense(s,3);strokeChanged=true;}}if(!area.cells.length)area.open=false;renderer.rev=-1;renderer.areaRev=-1;}
const points=new Map();let gesture=null,strokeBefore=null,strokeChanged=false,lastPaint=null;
function preview(p){let w=renderer.world(p.x,p.y),x=Math.floor(w.x),y=Math.floor(w.y);ui.cursor={x,y};if(!BUILDINGS[ui.tool]){ui.placement=null;return;}let key=[ui.tool,x,y,ui.moving,s.navVersion,s.cash].join(':');if(ui.placement?.key===key)return;let error=canPlace(s,ui.tool,x,y,ui.moving);if(!ui.moving&&['lab','league'].includes(ui.tool)&&s.buildings.some(b=>b.type===ui.tool))error='Already built';if(!ui.moving&&ui.tool==='gym'&&s.buildings.filter(b=>b.type==='gym').length>=8)error='Eight gyms already built';if(s.cash<(ui.moving?80:BUILDINGS[ui.tool].cost))error='Not enough money';ui.placement={key,x,y,error};}
function eventPoint(e){let r=$('world').getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top};}
function paintLine(p){let to={x:Math.floor(p.x),y:Math.floor(p.y)},from=lastPaint||to,n=Math.max(Math.abs(to.x-from.x),Math.abs(to.y-from.y),1);for(let i=0;i<=n;i++)paintAt(Math.round(from.x+(to.x-from.x)*i/n),Math.round(from.y+(to.y-from.y)*i/n));lastPaint=to;}
function pair(){let [a,b]=[...points.values()];return {x:(a.x+b.x)/2,y:(a.y+b.y)/2,d:Math.hypot(a.x-b.x,a.y-b.y)};}
$('world').addEventListener('pointerdown',e=>{if(!sessionReady)return;e.preventDefault();$('world').setPointerCapture(e.pointerId);let p=eventPoint(e);points.set(e.pointerId,p);if(points.size===2){ui.cursor=null;ui.placement=null;if(strokeBefore){restoreEdit(strokeBefore);strokeBefore=null;strokeChanged=false;}let q=pair();gesture={kind:'pinch',...q,zoom:renderer.camera.zoom,camera:{...renderer.camera}};return;}if(points.size>2)return;gesture={kind:'single',start:p,last:p,moved:false,building:ui.build&&!!BUILDINGS[ui.tool]};preview(p);if(ui.build&&(TERRAIN[ui.tool]||['area','areaErase'].includes(ui.tool))){strokeBefore=editSnapshot();strokeChanged=false;lastPaint=null;paintLine(renderer.world(p.x,p.y));}});
$('world').addEventListener('pointermove',e=>{let p=eventPoint(e),w=renderer.world(p.x,p.y);if(points.size<2)preview(p);if(!points.has(e.pointerId))return;points.set(e.pointerId,p);if(points.size>=2){if(gesture?.kind!=='pinch')return;let q=pair(),g=gesture,z=clamp(g.zoom*q.d/Math.max(1,g.d),.45,4);let wx=g.camera.x+(g.x-renderer.w/2)/g.zoom,wy=g.camera.y+(g.y-renderer.h/2)/g.zoom;renderer.camera.zoom=z;renderer.camera.x=wx-(q.x-renderer.w/2)/z;renderer.camera.y=wy-(q.y-renderer.h/2)/z;ui.follow=null;return;}if(!gesture||gesture.kind!=='single')return;if(Math.hypot(p.x-gesture.start.x,p.y-gesture.start.y)>8)gesture.moved=true;if(ui.build&&(TERRAIN[ui.tool]||['area','areaErase'].includes(ui.tool))&&strokeBefore)paintLine(w);else if(!ui.build||!ui.tool||ui.tool==='pan'){renderer.camera.x-=(p.x-gesture.last.x)/renderer.camera.zoom;renderer.camera.y-=(p.y-gesture.last.y)/renderer.camera.zoom;ui.follow=null;}gesture.last=p;});
function pointerEnd(e,cancel=false){if(!points.has(e.pointerId))return;let p=points.get(e.pointerId);points.delete(e.pointerId);if(points.size)return;let g=gesture;gesture=null;if(strokeBefore){if(cancel||!validateRoutes()){restoreEdit(strokeBefore);if(!cancel)toast('Keep all building entrances connected and trainers on dry land.');}else if(strokeChanged)commitEdit(strokeBefore);strokeBefore=null;strokeChanged=false;lastPaint=null;return;}if(cancel||g?.kind!=='single'){ui.cursor=null;ui.placement=null;return;}if(g.moved&&!g.building)return;let w=renderer.world(p.x,p.y);if(ui.build){if(BUILDINGS[ui.tool])place(Math.floor(w.x),Math.floor(w.y));}else inspectMap(w);}
$('world').addEventListener('pointerup',e=>pointerEnd(e));$('world').addEventListener('pointercancel',e=>pointerEnd(e,true));$('world').addEventListener('wheel',e=>{e.preventDefault();let p=eventPoint(e),w=renderer.world(p.x,p.y),z=clamp(renderer.camera.zoom*Math.exp(-e.deltaY*.001),.45,4);renderer.camera.zoom=z;renderer.camera.x=w.x*TILE-(p.x-renderer.w/2)/z;renderer.camera.y=w.y*TILE-(p.y-renderer.h/2)/z;},{passive:false});
function inspectMap(w){let b=s.battles.find(b=>dist({x:b.x+.5,y:b.y+1.4},w)<1.8);if(b){ui.battle=b.id;openPanel('battle');return;}let t=[...s.trainers].sort((a,b)=>dist(a,w)-dist(b,w))[0];if(t&&dist({x:t.x+.5,y:t.y+.5},w)<1){ui.selectedTrainer=t.id;openPanel('trainer');return;}let building=buildingAt(s,Math.floor(w.x),Math.floor(w.y));if(building){ui.selectedBuilding=building.id;openPanel('building');return;}let area=(s.areas||[]).find(a=>{let p=areaMarker(a);return p&&dist(p,w)<1.5;})||areaAt(s,Math.floor(w.x),Math.floor(w.y));if(area){ui.selectedArea=area.id;openPanel('area');return;}if(!owned(s,Math.floor(w.x),Math.floor(w.y))){openPanel('region');return;}closePanel();}
